(()=>{const edition=new URLSearchParams(location.search).get('edition')==='law'?'law':'one',name=edition==='law'?'Vibe Law':'Vibe One';try{localStorage.setItem('vibe-edition',edition);}catch{}document.title=name+' · Your space';document.body.dataset.edition=edition;document.querySelector('#space-logo').src='/brand/vibe-'+edition+'-logo.svg';document.querySelector('#space-logo').alt=name;document.querySelector('#space-footer').textContent=name;if(edition==='law'){document.querySelector('#space-heading').textContent='Build a better way to do legal work.';document.querySelector('#space-description').textContent='Bring your legal technology idea into a focused space. Define the workflow, explore design references, and build your first useful version.';}const links=[['Open Workbench','overview'],['Build a project','build'],['Write a project brief','project'],['Browse playbooks','library'],['Design resources','resources'],['Compare demo plans','plans'],['Creator demo checkout','creator'],['Team demo checkout','team']];for(const [label,target] of links){const a=document.createElement('a');a.textContent=label;a.href=target==='plans'?'/plans/?edition='+edition:['creator','team'].includes(target)?'/checkout/?edition='+edition+'&plan='+target:'/account/?edition='+edition+'#'+target;document.querySelector('#space-links').append(a);}})();